package com.nova.service;
import com.nova.jobs.BackgroundJob;
import com.nova.jobs.BackgroundJobRepository;
import org.springframework.stereotype.Service;import org.springframework.transaction.support.TransactionSynchronization;import org.springframework.transaction.support.TransactionSynchronizationManager;import java.util.ArrayList;import java.util.List;@Service public class BackgroundJobService {private final BackgroundJobRepository repository;private final BackgroundJobProcessor processor;public BackgroundJobService(BackgroundJobRepository repository,BackgroundJobProcessor processor){this.repository=repository;this.processor=processor;}public void startOrderJobs(Long orderId){List<Long> ids=new ArrayList<>();for(String type:List.of("EMAIL","INVOICE","NOTIFICATION")){if(!repository.existsByOrderIdAndJobType(orderId,type)){BackgroundJob saved=repository.save(new BackgroundJob(orderId,type));ids.add(saved.getId());}}Runnable dispatch=()->ids.forEach(processor::process);if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){dispatch.run();}});else dispatch.run();}}
